def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = {}
    for k, v in opponents_status.items():
        if v.get('alive'):
            alive[k] = v

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0 if hp > 3 else 35.0))

    bob = opponents_status.get('Bob', None)
    cindy = opponents_status.get('Cindy', None)

    bob_prev_bid = None
    bob_pressure = 0.0
    if bob and bob.get('alive'):
        prev = bob.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bob_prev_bid = prev.get('bid')
            bob_pressure = bob_prev_bid
        else:
            bob_pressure = 75.0

    cindy_prev_bid = None
    if cindy and cindy.get('alive'):
        prev = cindy.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            cindy_prev_bid = prev.get('bid')

    alive_count = len(alive)

    desperate = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1

    if desperate:
        target = 92.0
        if bob_pressure > 0:
            target = max(target, bob_pressure + 3.0)
        if cindy_prev_bid is not None and cindy_prev_bid < 120:
            target = max(target, cindy_prev_bid + 2.0)
        return float(min(budget, target))

    if pressured:
        target = 78.0
        if bob_pressure > 80:
            target = bob_pressure + 1.5
        elif bob_pressure > 0:
            target = max(76.0, bob_pressure + 0.5)
        if alive_count >= 3:
            target += 2.0
        return float(min(budget, target))

    if day <= 3:
        if cindy_prev_bid is not None and cindy_prev_bid >= 150:
            return float(min(budget, 48.0))
        if bob_pressure >= 80:
            return float(min(budget, 58.0))
        return float(min(budget, 62.0))

    if alive_count == 1 and bob and bob.get('alive'):
        if hp >= bob.get('hp', 0) and budget > bob.get('budget', 0):
            return float(min(budget, max(72.0, bob_pressure + 1.0 if bob_pressure else 72.0)))
        return float(min(budget, 68.0 if hp > 3 else 82.0))

    if bob_pressure >= 85:
        return float(min(budget, 50.0))
    if bob_pressure >= 75:
        return float(min(budget, 57.0))

    base = 54.0
    if alive_count >= 3:
        base = 59.0
    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    # Use yesterday trace to infer who is pressuring the market
    cindy_prev_bid = None
    max_prev_bid = None
    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is None:
            continue
        if max_prev_bid is None:
            max_prev_bid = float(bid)
        else:
            max_prev_bid = max(max_prev_bid, float(bid))
        if opp_id == 'Cindy':
            cindy_prev_bid = float(bid)

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Determine a target bid band.
    # If Cindy previously bid very high, we anticipate a high clearing price and bid more to secure water.
    # Otherwise, bid conservatively to avoid overpaying.
    if cindy_prev_bid is not None and cindy_prev_bid >= 0.9 * 191.1:
        # High pressure from Cindy
        if hp > 4:
            bid = DAILY_SALARY * 0.55
        else:
            bid = DAILY_SALARY * 0.85
    elif max_prev_bid is not None and max_prev_bid >= DAILY_SALARY * 2.0:
        # Someone is splurging; slightly increase to stay competitive
        if hp > 4:
            bid = DAILY_SALARY * 0.6
        else:
            bid = DAILY_SALARY * 0.9
    else:
        # Market not extremely pressured; moderate bid
        if hp > 6:
            bid = DAILY_SALARY * 0.48
        elif hp > 3:
            bid = DAILY_SALARY * 0.62
        else:
            bid = DAILY_SALARY * 0.88

    # Ensure we don't bid more than budget and keep within a reasonable cap.
    bid = max(0.0, min(bid, budget))

    # If supply is low relative to our requirement, we should be more aggressive.
    # supply is between 15 and 25; if closer to 15, competition higher.
    if supply <= 16.0:
        bid = min(budget, bid * 1.15)
    elif supply >= 22.0:
        bid = bid * 0.95

    # Small day-based dithering to avoid ties.
    # Use int(day) for index safety.
    bid = bid + (0.5 if (day % 2 == 0) else 0.0)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 1.2)
    elif supply < 18:
        bid = min(my_status['budget'], max(avg_prev_bid * 1.1, DAILY_SALARY * 0.8))
    else:
        bid = min(my_status['budget'], max(avg_prev_bid * 0.9, DAILY_SALARY * 0.5))

    return float(bid)
